const express = require('express');
const app = express();

app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.post('/users', (req, res) => {
  const { name } = req.body;

  // Validate that name exists and is a string
  if (!name) {
    return res.status(400).json({
      error: 'Missing required field: name',
      message: 'The name field is required and cannot be empty'
    });
  }

  if (typeof name !== 'string') {
    return res.status(400).json({
      error: 'Invalid field type: name',
      message: 'The name field must be a string'
    });
  }

  // In a real app, we would save the user to a database
  // For now, we'll just return the user data with a generated id
  const newUser = {
    id: Date.now(), // Simple ID generation
    name,
    email: `${name.toLowerCase()}@example.com`
  };

  res.status(201).json(newUser);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

